use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g1-column-tiles176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g1-column-tiles176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn files(base:&Path,p:&Path,v:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let t=e.file_type().unwrap();assert!(!t.is_symlink());if t.is_dir(){files(base,&e.path(),v);}else{assert!(t.is_file());v.push(e.path().strip_prefix(base).unwrap().to_path_buf());}}}
fn main(){let r=Path::new(R);let d=Path::new(D);let root=r.join("archive-review");assert!(!root.exists());fs::create_dir(&root).unwrap();let mut totals=vec![];for name in["source","receipts","workflow","codegen"]{let dest=root.join(name);fs::create_dir(&dest).unwrap();assert!(Command::new("tar").arg("-xzf").arg(d.join(format!("artifacts/{name}.tar.gz"))).arg("-C").arg(&dest).status().unwrap().success());let mut all=vec![];files(&dest,&dest,&mut all);for p in &all{assert_eq!(hash(dest.join(p)),hash(r.join(p)));let t=p.to_string_lossy();assert!(!t.ends_with("-sdk")&&!t.ends_with(".words")&&!t.ends_with(".expected")&&!t.ends_with(".a1q"));}if name=="source"{assert_eq!(all.len(),178);for(rel,h)in read(r.join("source-audit.json"))["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(dest.join("source").join(rel)),h.as_str().unwrap());}}if name=="receipts"{assert_eq!(all.iter().filter(|p|p.starts_with("runs")&&p.file_name().unwrap()=="stdout.log").count(),220);assert_eq!(all.iter().filter(|p|p.starts_with("stat")&&p.extension().is_some_and(|s|s=="csv")).count(),4);}totals.push(json!({"archive":name,"byte_exact_members":all.len()}));}
for n in["analysis.json","symbols.json","review.json","review.log","codegen.json","counts.json","source-audit.json","design.md","capture-design.md"]{assert_eq!(hash(d.join("artifacts").join(n)),hash(r.join(n)));}
let text=fs::read_to_string(d.join("README.md")).unwrap();let mut rest=text.as_str();let mut links=0;while let Some(i)=rest.find("]("){rest=&rest[i+2..];let end=rest.find(')').unwrap();let p=&rest[..end];if !p.starts_with("https://")&&!p.starts_with('#'){assert!(d.join(p).exists(),"{p}");links+=1;}rest=&rest[end+1..];}assert_eq!(read(d.join("artifacts/analysis.json"))["caller_gate_passed"],false);let out=json!({"passed":true,"archives":totals,"README_local_links_present":links,"private_input_and_binary_exclusion_checked":true,"failed_gate_preserved":true,"scope":"All four archives extracted and byte-compared;178source files/220capture command streams/fourrawPMU CSVs verified. No tests/models/solves/captures/proofs rerun."});fs::write(d.join("artifacts/archive-review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Archive closurePASS;4archives byteexact/178source/220capturestreams/4PMU;{links}links");}
